<?php require_once __DIR__.'/../config/db.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id_producto']??0);$data=[trim($_POST['codigo']),trim($_POST['nombre']),(int)$_POST['id_categoria'],(float)$_POST['precio_compra'],(float)$_POST['precio_venta'],(int)$_POST['cantidad'],(int)$_POST['stock_minimo'],$_POST['fecha_vencimiento']?:null];if($id){$s=$pdo->prepare('UPDATE productos SET codigo=?,nombre=?,id_categoria=?,precio_compra=?,precio_venta=?,cantidad=?,stock_minimo=?,fecha_vencimiento=? WHERE id_producto=?');$s->execute(array_merge($data,[$id]));}else{$s=$pdo->prepare('INSERT INTO productos(codigo,nombre,id_categoria,precio_compra,precio_venta,cantidad,stock_minimo,fecha_vencimiento) VALUES(?,?,?,?,?,?,?,?)');$s->execute($data);}header('Location: productos.php');exit;}if(isset($_GET['eliminar'])){$s=$pdo->prepare('DELETE FROM productos WHERE id_producto=?');$s->execute([(int)$_GET['eliminar']]);header('Location: productos.php');exit;}$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM productos WHERE id_producto=?');$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}$cats=$pdo->query('SELECT * FROM categorias ORDER BY nombre')->fetchAll();$rows=$pdo->query('SELECT p.*,c.nombre categoria FROM productos p JOIN categorias c ON c.id_categoria=p.id_categoria ORDER BY p.nombre')->fetchAll();$title='Productos';require 'header.php';?><h2>Productos</h2><div class="card mb-4"><div class="card-body"><h5><?=$edit?'Editar':'Registrar'?> producto</h5><form method="post" class="row g-2"><input type="hidden" name="id_producto" value="<?=e($edit['id_producto']??'')?>"><div class="col-md-2"><input class="form-control" name="codigo" placeholder="Código" required value="<?=e($edit['codigo']??'')?>"></div><div class="col-md-3"><input class="form-control" name="nombre" placeholder="Nombre" required value="<?=e($edit['nombre']??'')?>"></div><div class="col-md-2"><select class="form-select" name="id_categoria" required><option value="">Categoría</option><?php foreach($cats as $c):?><option value="<?=$c['id_categoria']?>" <?= (($edit['id_categoria']??'')==$c['id_categoria'])?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach;?></select></div><div class="col-md-1"><input class="form-control" type="number" step="0.01" name="precio_compra" placeholder="Compra" required value="<?=e($edit['precio_compra']??'')?>"></div><div class="col-md-1"><input class="form-control" type="number" step="0.01" name="precio_venta" placeholder="Venta" required value="<?=e($edit['precio_venta']??'')?>"></div><div class="col-md-1"><input class="form-control" type="number" name="cantidad" placeholder="Stock" required value="<?=e($edit['cantidad']??0)?>"></div><div class="col-md-1"><input class="form-control" type="number" name="stock_minimo" placeholder="Mín." required value="<?=e($edit['stock_minimo']??0)?>"></div><div class="col-md-1"><input class="form-control" type="date" name="fecha_vencimiento" value="<?=e($edit['fecha_vencimiento']??'')?>"></div><div class="col-12"><button class="btn btn-primary">Guardar producto</button></div></form></div></div><div class="card"><div class="card-body"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Venta</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$alert=$r['cantidad']<=$r['stock_minimo'];?><tr><td><?=e($r['codigo'])?></td><td><?=e($r['nombre'])?></td><td><?=e($r['categoria'])?></td><td>$<?=number_format($r['precio_venta'],0,',','.')?></td><td><?=$r['cantidad']?></td><td><span class="badge <?=$alert?'text-bg-warning':'text-bg-success'?>"><?=$alert?'Bajo stock':'Disponible'?></span></td><td><a href="?editar=<?=$r['id_producto']?>">Editar</a> · <a class="text-danger" href="?eliminar=<?=$r['id_producto']?>" onclick="return confirm('¿Eliminar producto?')">Eliminar</a></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require 'footer.php';
